+    const status = current?.status;
+    if (status === "READY" && current?.queryable === true) {
+      return;
+    }
+    await new Promise((resolve) => setTimeout(resolve, pollMs));
+  }
+
+  throw new Error(`timed out waiting for graph search index ${indexName}`);
