 }

 export async function getHydrationCache(): Promise<CacheHandle> {
-  hydrationCachePromise ??= createHydrationCache();
+  hydrationCachePromise ??= createHydrationCache().catch((error) => {
+    hydrationCachePromise = null;
+    throw error;
+  });
